fn battle(hp: *i32, maxHp: i32, atk: i32, potions: *i32,
           mHp: *i32, mAtk: i32, mGold: i32,
           seed: *i32, state: *i32, gold: *i32) {
    while *hp > 0 {
        printf("你的 HP: %d/%d\n", *hp, maxHp);
        printf("怪物 HP: %d\n", *mHp);
        puts("1. 攻击");
        puts("2. 喝药 (+6 HP)");
        puts("3. 逃跑");
        puts("选择行动:");

        let mut choice = 0;
        scanf("%d", &choice);

        // 攻击
        if choice == 1 {
            let dmg = atk + randRange(seed, -1, 1);
            let curMhp = *mHp;
            let newMhp = curMhp - dmg;
            *mHp = newMhp;
            printf("你造成了 %d 点伤害。\n", dmg);
        }
        // 喝药
        if choice == 2 {
            if *potions > 0 {
                let curHp = *hp;
                let newHp = curHp + 6;
                *hp = newHp;
                *hp = clamp(*hp, 0, maxHp);
                let curPot = *potions;
                let newPot = curPot - 1;
                *potions = newPot;
                puts("你喝下一瓶药。");
            } else {
                puts("你没有药水！");
            }
        }
        // 逃跑
        if choice == 3 {
            let escape = randRange(seed, 0, 1);
            if escape == 0 {
                puts("逃跑失败！");
            } else {
                puts("你逃跑了。");
            }
            if escape != 0 { return; }
        }

        // 检查怪物是否被击杀
        if *mHp <= 0 {
            puts("你击败了怪物！");
            let newGold = *gold + mGold;
            *gold = newGold;
            return;
        }

        // 怪物反击
        let dmg = mAtk + randRange(seed, -1, 1);
        let curHp2 = *hp;
        let newHp2 = curHp2 - dmg;
        *hp = newHp2;
        printf("怪物造成了 %d 点伤害。\n", dmg);
    }

    // 玩家死亡
    *state = 2;
}

